const uASBySerialFold = `-- name: UASBySerialFold :many
SELECT id, operator_id, serial, serial_fold, manufacturer_code, registration_mark, manufacturer, model, owner_ref, class_label, mtom_g, rid_capability, status, status_reason, registered_at, registry_version, created_by, updated_at, updated_by FROM uas WHERE serial_fold = $1 ORDER BY id
`

// Every aircraft whose serial folds to the key (at most one: serial_fold
// is unique; the caller still refuses more than one, G-05).
func (q *Queries) UASBySerialFold(ctx context.Context, serialFold string) ([]UAS, error) {
	rows, err := q.db.Query(ctx, uASBySerialFold, serialFold)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UAS{}
	for rows.Next() {
		var i UAS
		if err := rows.Scan(
			&i.ID,
			&i.OperatorID,
			&i.Serial,
			&i.SerialFold,
			&i.ManufacturerCode,
			&i.RegistrationMark,
			&i.Manufacturer,
			&i.Model,
			&i.OwnerRef,
			&i.ClassLabel,
			&i.MtomG,
			&i.RidCapability,
			&i.Status,
			&i.StatusReason,
			&i.RegisteredAt,
			&i.RegistryVersion,
			&i.CreatedBy,
			&i.UpdatedAt,
			&i.UpdatedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

